WITH base AS (SELECT *, TRIM(method) AS clean_method FROM payments WHERE order_id IN (2, 40) AND order_id = 33), agg AS (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, order_id, SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END) AS failed_count, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) AS success_count FROM base GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END, order_id) SELECT paid_cohort, failed_count, success_count FROM agg WHERE success_count >= 7;
